import math


def _ensure_finite(value):
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            raise ValueError("non-finite number found in payload")
    elif isinstance(value, dict):
        for v in value.values():
            _ensure_finite(v)
    elif isinstance(value, list):
        for v in value:
            _ensure_finite(v)


def _unwrap(obj):
    if isinstance(obj, dict) and set(obj) == {"name", "result"}:
        return obj["result"]
    return obj


def _nonempty_text(v):
    return isinstance(v, str) and v.strip() != ""


def _parse_field(f):
    if not isinstance(f, dict):
        raise ValueError("field must be an object")
    if "name" not in f or "type" not in f or "required" not in f:
        raise ValueError("field is missing name/type/required")
    name = f["name"]
    if not _nonempty_text(name):
        raise ValueError("field name must be non-empty text")
    name = name.strip()
    ftype = f["type"]
    if ftype not in ("int", "float", "str", "bool"):
        raise ValueError("field type must be one of int/float/str/bool")
    req = f["required"]
    if not isinstance(req, bool):
        raise ValueError("required must be a bool")
    return {"name": name, "type": ftype, "required": req, "default": "default" in f}


def _parse_fields(raw):
    if not isinstance(raw, list):
        raise ValueError("old/new must be lists")
    out = []
    seen = set()
    for f in raw:
        p = _parse_field(f)
        if p["name"] in seen:
            raise ValueError("duplicate normalized field name")
        seen.add(p["name"])
        out.append(p)
    return out


def _parse_renames(raw):
    if not isinstance(raw, list):
        raise ValueError("renames must be a list")
    out = []
    seen_from = set()
    for r in raw:
        if not isinstance(r, dict):
            raise ValueError("rename must be an object")
        if "from" not in r or "to" not in r:
            raise ValueError("rename is missing from/to")
        fr = r["from"]
        to = r["to"]
        if not _nonempty_text(fr) or not _nonempty_text(to):
            raise ValueError("rename from/to must be non-empty text")
        fr = fr.strip()
        to = to.strip()
        if fr in seen_from:
            raise ValueError("duplicate rename from")
        seen_from.add(fr)
        out.append((fr, to))
    return out


def _detect_cycle(edges):
    WHITE, GRAY, BLACK = 0, 1, 2
    nodes = set(edges.keys()) | set(edges.values())
    color = {n: WHITE for n in nodes}

    def visit(n):
        color[n] = GRAY
        nxt = edges.get(n)
        if nxt is not None:
            if color.get(nxt, WHITE) == GRAY:
                return True
            if color.get(nxt, WHITE) == WHITE and visit(nxt):
                return True
        color[n] = BLACK
        return False

    for n in nodes:
        if color[n] == WHITE and visit(n):
            return True
    return False


def _terminal(edges, name):
    cur = name
    while cur in edges:
        cur = edges[cur]
    return cur


def transform(payloads, contract):
    if not isinstance(payloads, list) or len(payloads) != len(contract.get("inputs", [])):
        raise ValueError("payloads must match contract inputs order")
    _ensure_finite(payloads)

    obj = _unwrap(payloads[0])
    if not isinstance(obj, dict):
        raise ValueError("schema_migration input must be an object")
    if "old" not in obj or "new" not in obj or "renames" not in obj:
        raise ValueError("schema_migration input is missing old/new/renames")

    old_fields = _parse_fields(obj["old"])
    new_fields = _parse_fields(obj["new"])
    renames = _parse_renames(obj["renames"])

    edges = dict(renames)
    if _detect_cycle(edges):
        raise ValueError("rename graph contains a cycle")

    field_map = {}
    term_to_old = {}
    for f in old_fields:
        t = _terminal(edges, f["name"])
        if t in term_to_old:
            raise ValueError("different old fields normalize to the same terminal")
        term_to_old[t] = f["name"]
        field_map[f["name"]] = t

    renamed_old = {field_map[f["name"]]: f for f in old_fields}
    new_by_name = {f["name"]: f for f in new_fields}

    all_names = sorted(set(renamed_old) | set(new_by_name))
    changes = []
    any_breaking = False

    for name in all_names:
        in_old = name in renamed_old
        in_new = name in new_by_name
        if in_old and not in_new:
            changes.append({"field": name, "code": "removed", "breaking": True})
            any_breaking = True
        elif in_new and not in_old:
            nf = new_by_name[name]
            breaking = nf["required"] is True and not nf["default"]
            changes.append({"field": name, "code": "added", "breaking": breaking})
            if breaking:
                any_breaking = True
        else:
            of = renamed_old[name]
            nf = new_by_name[name]
            if of["type"] != nf["type"]:
                breaking = not (of["type"] == "int" and nf["type"] == "float")
                changes.append({"field": name, "code": "type", "breaking": breaking})
                if breaking:
                    any_breaking = True
            if of["required"] is False and nf["required"] is True:
                breaking = not nf["default"]
                changes.append({"field": name, "code": "required", "breaking": breaking})
                if breaking:
                    any_breaking = True

    result = {
        "compatible": not any_breaking,
        "changes": changes,
        "field_map": field_map,
    }
    return {"name": contract["name"], "result": result}

