import hashlib
import json
import math


def _ensure_finite(value):
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            raise ValueError("non-finite number found in payload")
    elif isinstance(value, dict):
        for v in value.values():
            _ensure_finite(v)
    elif isinstance(value, list):
        for v in value:
            _ensure_finite(v)


def _unwrap(obj):
    if isinstance(obj, dict) and set(obj) == {"name", "result"}:
        return obj["result"]
    return obj


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _nonempty_text(v):
    return isinstance(v, str) and v.strip() != ""


def _sha256(documents):
    s = json.dumps(
        documents,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )
    return hashlib.sha256(s.encode("utf-8")).hexdigest()


def transform(payloads, contract):
    if not isinstance(payloads, list) or len(payloads) != len(contract.get("inputs", [])):
        raise ValueError("payloads must match contract inputs order")
    _ensure_finite(payloads)

    obj = _unwrap(payloads[0])
    if not isinstance(obj, dict):
        raise ValueError("shard_replay input must be an object")
    if "replicas" not in obj or "events" not in obj:
        raise ValueError("shard_replay input is missing replicas/events")

    replicas_raw = obj["replicas"]
    if not isinstance(replicas_raw, list):
        raise ValueError("replicas must be a list")

    replicas = []
    replica_ids = set()
    for r in replicas_raw:
        if not isinstance(r, dict):
            raise ValueError("replica must be an object")
        for k in ("id", "shard", "host", "checkpoint", "documents"):
            if k not in r:
                raise ValueError("replica is missing field %s" % k)
        rid = r["id"]
        if not _nonempty_text(rid):
            raise ValueError("replica id must be non-empty text")
        if rid in replica_ids:
            raise ValueError("duplicate replica id")
        replica_ids.add(rid)
        shard = r["shard"]
        host = r["host"]
        if not _nonempty_text(shard):
            raise ValueError("shard must be non-empty text")
        if not _nonempty_text(host):
            raise ValueError("host must be non-empty text")
        checkpoint = r["checkpoint"]
        if not _is_int(checkpoint) or checkpoint < -1:
            raise ValueError("checkpoint must be an int >= -1")
        docs_raw = r["documents"]
        if not isinstance(docs_raw, list):
            raise ValueError("documents must be a list")
        documents = {}
        seen_doc = set()
        for d in docs_raw:
            if not isinstance(d, dict):
                raise ValueError("document must be an object")
            for k in ("id", "version", "fields"):
                if k not in d:
                    raise ValueError("document is missing field %s" % k)
            did = d["id"]
            if not _nonempty_text(did):
                raise ValueError("document id must be non-empty text")
            if did in seen_doc:
                raise ValueError("duplicate initial document id")
            seen_doc.add(did)
            ver = d["version"]
            if not _is_int(ver) or ver < 0:
                raise ValueError("document version must be an int >= 0")
            fields = d["fields"]
            if not isinstance(fields, dict):
                raise ValueError("document fields must be an object")
            documents[did] = (ver, fields)
        replicas.append(
            {
                "id": rid,
                "shard": shard,
                "host": host,
                "checkpoint": checkpoint,
                "documents": documents,
            }
        )

    events_raw = obj["events"]
    if not isinstance(events_raw, list):
        raise ValueError("events must be a list")

    events_by_key = {}
    for e in events_raw:
        if not isinstance(e, dict):
            raise ValueError("event must be an object")
        for k in ("replica", "offset", "epoch", "op", "id", "version"):
            if k not in e:
                raise ValueError("event is missing field %s" % k)
        rep = e["replica"]
        if not _nonempty_text(rep):
            raise ValueError("event replica must be non-empty text")
        if rep not in replica_ids:
            raise ValueError("unknown replica")
        offset = e["offset"]
        if not _is_int(offset) or offset < 0:
            raise ValueError("offset must be an int >= 0")
        epoch = e["epoch"]
        if not _is_int(epoch) or epoch < 0:
            raise ValueError("epoch must be an int >= 0")
        op = e["op"]
        if op not in ("upsert", "delete"):
            raise ValueError("op must be upsert or delete")
        did = e["id"]
        if not _nonempty_text(did):
            raise ValueError("event id must be non-empty text")
        ver = e["version"]
        if not _is_int(ver) or ver < 0:
            raise ValueError("version must be an int >= 0")
        if op == "upsert":
            if "fields" not in e or not isinstance(e["fields"], dict):
                raise ValueError("upsert event requires a fields object")
        events_by_key.setdefault((rep, offset), []).append(e)

    # Resolve epoch conflicts for every (replica, offset), including events
    # before the checkpoint and after the first gap.
    effective = {}
    for key, evs in events_by_key.items():
        max_epoch = max(ev["epoch"] for ev in evs)
        top = [ev for ev in evs if ev["epoch"] == max_epoch]
        first = top[0]
        for ev in top[1:]:
            if ev != first:
                raise ValueError("conflicting events at the same offset and epoch")
        effective[key] = first

    result_replicas = []
    for rep in replicas:
        state = {}
        for did, (ver, fields) in rep["documents"].items():
            state[did] = ("doc", ver, fields)

        applied = rep["checkpoint"]
        offset = rep["checkpoint"] + 1
        while (rep["id"], offset) in effective:
            ev = effective[(rep["id"], offset)]
            did = ev["id"]
            ver = ev["version"]
            op = ev["op"]
            if op == "upsert":
                fields = ev["fields"]
                if did not in state:
                    state[did] = ("doc", ver, fields)
                else:
                    kind = state[did][0]
                    old_ver = state[did][1]
                    if ver > old_ver:
                        state[did] = ("doc", ver, fields)
                    elif ver == old_ver:
                        if kind == "doc" and state[did][2] == fields:
                            pass
                        else:
                            raise ValueError("document version conflict")
            else:  # delete
                if did not in state:
                    state[did] = ("tomb", ver)
                else:
                    kind = state[did][0]
                    old_ver = state[did][1]
                    if ver > old_ver:
                        state[did] = ("tomb", ver)
                    elif ver == old_ver:
                        if kind == "tomb":
                            pass
                        else:
                            raise ValueError("document version conflict (delete vs upsert)")
            applied = offset
            offset += 1

        docs_out = []
        tombstones = {}
        for did in sorted(state.keys()):
            st = state[did]
            if st[0] == "doc":
                docs_out.append({"id": did, "version": st[1], "fields": st[2]})
            else:
                tombstones[did] = st[1]

        result_replicas.append(
            {
                "id": rep["id"],
                "shard": rep["shard"],
                "host": rep["host"],
                "applied_offset": applied,
                "documents": docs_out,
                "tombstones": tombstones,
                "sha256": _sha256(docs_out),
            }
        )

    result_replicas.sort(key=lambda r: r["id"])
    return {"name": contract["name"], "result": {"replicas": result_replicas}}

