            if "fields" not in e or not isinstance(e["fields"], dict):
                raise ValueError("upsert event requires a fields object")
        events_by_key.setdefault((rep, offset), []).append(e)

    # Resolve epoch conflicts for every (replica, offset), including events
    # before the checkpoint and after the first gap.
    effective = {}
    for key, evs in events_by_key.items():
        max_epoch = max(ev["epoch"] for ev in evs)
        top = [ev for ev in evs if ev["epoch"] == max_epoch]
        first = top[0]
        for ev in top[1:]:
