            state[did] = ("doc", ver, fields)

        applied = rep["checkpoint"]
        offset = rep["checkpoint"] + 1
        while (rep["id"], offset) in effective:
            ev = effective[(rep["id"], offset)]
            did = ev["id"]
            ver = ev["version"]
            op = ev["op"]
            if op == "upsert":
                fields = ev["fields"]
                if did not in state:
                    state[did] = ("doc", ver, fields)
                else:
                    kind = state[did][0]
                    old_ver = state[did][1]
                    if ver > old_ver:
                        state[did] = ("doc", ver, fields)
                    elif ver == old_ver:
                        if kind == "doc" and state[did][2] == fields:
                            pass
