            offset += 1

        docs_out = []
        tombstones = {}
        for did in sorted(state.keys()):
            st = state[did]
            if st[0] == "doc":
                docs_out.append({"id": did, "version": st[1], "fields": st[2]})
            else:
                tombstones[did] = st[1]

        result_replicas.append(
            {
                "id": rep["id"],
                "shard": rep["shard"],
                "host": rep["host"],
                "applied_offset": applied,
                "documents": docs_out,
                "tombstones": tombstones,
                "sha256": _sha256(docs_out),
            }
        )

    result_replicas.sort(key=lambda r: r["id"])
    return {"name": contract["name"], "result": {"replicas": result_replicas}}

