import itertools
import math
import re
from collections import defaultdict

_DIGEST_RE = re.compile(r"^[0-9a-fA-F]{64}$")


def _ensure_finite(value):
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            raise ValueError("non-finite number found in payload")
    elif isinstance(value, dict):
        for v in value.values():
            _ensure_finite(v)
    elif isinstance(value, list):
        for v in value:
            _ensure_finite(v)


def _unwrap(obj):
    if isinstance(obj, dict) and set(obj) == {"name", "result"}:
        return obj["result"]
    return obj


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _nonempty_text(v):
    return isinstance(v, str) and v.strip() != ""


def _host_combos(cands, k):
    res = []
    n = len(cands)
    for combo in itertools.combinations(range(n), k):
        hosts = [cands[i]["host"] for i in combo]
        if len(set(hosts)) == k:
            res.append([cands[i] for i in combo])
    return res


def transform(payloads, contract):
    if not isinstance(payloads, list) or len(payloads) != len(contract.get("inputs", [])):
        raise ValueError("payloads must match contract inputs order")
    _ensure_finite(payloads)
    if len(payloads) != 3:
        raise ValueError("quorum_cutover requires exactly 3 inputs")

    local = _unwrap(payloads[0])
    schema = _unwrap(payloads[1])
    shard = _unwrap(payloads[2])

    if not isinstance(local, dict):
        raise ValueError("quorum_cutover input must be an object")
    if "partitions" not in local or "candidates" not in local or "budget" not in local:
        raise ValueError("quorum_cutover input is missing partitions/candidates/budget")

    partitions_raw = local["partitions"]
    candidates_raw = local["candidates"]
    budget = local["budget"]
    if not _is_int(budget) or budget < 0:
        raise ValueError("budget must be an int >= 0")
    if not isinstance(partitions_raw, list):
        raise ValueError("partitions must be a list")
    if not isinstance(candidates_raw, list):
        raise ValueError("candidates must be a list")

    # Read the shard_replay result and index replicas.
    if not isinstance(shard, dict) or "replicas" not in shard:
        raise ValueError("shard_replay result is missing replicas")
    replicas_list = shard["replicas"]
    if not isinstance(replicas_list, list):
        raise ValueError("replicas must be a list")
    replica_by_id = {}
    for r in replicas_list:
        if not isinstance(r, dict):
            raise ValueError("replica must be an object")
        for k in ("id", "shard", "host", "applied_offset", "sha256"):
            if k not in r:
                raise ValueError("replica is missing field %s" % k)
        rid = r["id"]
        if not _nonempty_text(rid):
            raise ValueError("replica id must be non-empty text")
        if not _nonempty_text(r["shard"]):
            raise ValueError("replica shard must be non-empty text")
        if not _nonempty_text(r["host"]):
            raise ValueError("replica host must be non-empty text")
        if not _is_int(r["applied_offset"]):
            raise ValueError("replica applied_offset must be an int")
        if not isinstance(r["sha256"], str):
            raise ValueError("replica sha256 must be a string")
        replica_by_id[rid] = r

    partitions = []
    partition_ids = set()
    for p in partitions_raw:
        if not isinstance(p, dict):
            raise ValueError("partition must be an object")
        for k in ("id", "quorum", "value", "target_sha256", "target_offset"):
            if k not in p:
                raise ValueError("partition is missing field %s" % k)
        pid = p["id"]
        if not _nonempty_text(pid):
            raise ValueError("partition id must be non-empty text")
        if pid in partition_ids:
            raise ValueError("duplicate partition id")
        partition_ids.add(pid)
        quorum = p["quorum"]
        if not _is_int(quorum) or quorum < 1:
            raise ValueError("quorum must be an int >= 1")
        value = p["value"]
        if not _is_int(value) or value < 0:
            raise ValueError("value must be an int >= 0")
        digest = p["target_sha256"]
        if not isinstance(digest, str) or not _DIGEST_RE.fullmatch(digest):
            raise ValueError("invalid digest")
        target_offset = p["target_offset"]
        if not _is_int(target_offset) or target_offset < -1:
            raise ValueError("target_offset must be an int >= -1")
        partitions.append(
            {
                "id": pid,
                "quorum": quorum,
                "value": value,
                "target_sha256": digest.lower(),
                "target_offset": target_offset,
            }
        )

    candidates = []
    candidate_ids = set()
    replica_seen = set()
    for c in candidates_raw:
        if not isinstance(c, dict):
            raise ValueError("candidate must be an object")
        for k in ("id", "replica", "cost"):
            if k not in c:
                raise ValueError("candidate is missing field %s" % k)
        cid = c["id"]
        if not _nonempty_text(cid):
            raise ValueError("candidate id must be non-empty text")
        if cid in candidate_ids:
            raise ValueError("duplicate candidate id")
        candidate_ids.add(cid)
        rep_id = c["replica"]
        if not _nonempty_text(rep_id):
            raise ValueError("candidate replica must be non-empty text")
        if rep_id not in replica_by_id:
            raise ValueError("unknown replica")
        if rep_id in replica_seen:
            raise ValueError("same replica referenced by multiple candidates")
        replica_seen.add(rep_id)
        cost = c["cost"]
        if not _is_int(cost) or cost < 0:
            raise ValueError("cost must be an int >= 0")
        rep = replica_by_id[rep_id]
        shard_id = rep["shard"]
        if shard_id not in partition_ids:
            raise ValueError("unknown shard")
        candidates.append({"id": cid, "replica": rep_id, "cost": cost, "shard": shard_id})

    # Schema result is validated after all reference/digest checks.
    if not isinstance(schema, dict) or "compatible" not in schema:
        raise ValueError("schema_migration result is missing compatible")
    if not isinstance(schema["compatible"], bool):
        raise ValueError("compatible must be a bool")

    if schema["compatible"] is False:
        return {
            "name": contract["name"],
            "result": {
                "blocked": True,
                "selected": [],
                "partitions": [],
                "value": 0,
                "cost": 0,
            },
        }

    part_by_id = {p["id"]: p for p in partitions}
    qual = defaultdict(list)
    for c in candidates:
        p = part_by_id[c["shard"]]
        rep = replica_by_id[c["replica"]]
        if rep["sha256"] == p["target_sha256"] and rep["applied_offset"] >= p["target_offset"]:
            qual[p["id"]].append({"id": c["id"], "cost": c["cost"], "host": rep["host"]})

    best_key = None
    best = ([], [], 0, 0)

    def search(idx, selected_ids, total_cost, total_value, satisfied):
        nonlocal best_key, best
        if idx == len(partitions):
            key = (-total_value, total_cost, tuple(sorted(selected_ids)))
            if best_key is None or key < best_key:
                best_key = key
                best = (
                    list(sorted(selected_ids)),
                    list(sorted(satisfied)),
                    total_value,
                    total_cost,
                )
            return
        p = partitions[idx]
        # Option 1: do not switch this partition at all.
        search(idx + 1, selected_ids, total_cost, total_value, satisfied)
        # Option 2: pick exactly quorum candidates on distinct hosts.
        for combo in _host_combos(qual[p["id"]], p["quorum"]):
            add_cost = sum(c["cost"] for c in combo)
            if total_cost + add_cost > budget:
                continue
            new_ids = selected_ids + [c["id"] for c in combo]
            search(
                idx + 1,
                new_ids,
                total_cost + add_cost,
                total_value + p["value"],
                satisfied + [p["id"]],
            )

    search(0, [], 0, 0, [])

    return {
        "name": contract["name"],
        "result": {
            "blocked": False,
            "selected": best[0],
            "partitions": best[1],
            "value": best[2],
            "cost": best[3],
        },
    }

