import json
import subprocess
import sys
from collections import deque
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _contracts():
    return sorted(
        p
        for p in ROOT.rglob("contract.json")
        if "outputs" not in p.relative_to(ROOT).parts
    )


def main():
    contracts = _contracts()
    if not contracts:
        raise ValueError("no component contracts found")

    info = {}
    for p in contracts:
        c = json.loads(p.read_text(encoding="utf-8"))
        info[c["name"]] = (c, p)

    output_to_name = {c["output"]: name for name, (c, _p) in info.items()}

    deps = {name: set() for name in info}
    for name, (c, _p) in info.items():
        for inp in c["inputs"]:
            if inp in output_to_name and output_to_name[inp] != name:
                deps[name].add(output_to_name[inp])

    dependents = {name: [] for name in info}
    in_deg = {}
    for name, ds in deps.items():
        in_deg[name] = len(ds)
        for d in ds:
            dependents[d].append(name)

    ready = deque(sorted(name for name in info if in_deg[name] == 0))
    order = []
    while ready:
        name = ready.popleft()
        order.append(name)
        for dep in sorted(dependents[name]):
            in_deg[dep] -= 1
            if in_deg[dep] == 0:
                ready.append(dep)

    if len(order) != len(info):
        raise ValueError("dependency cycle among components")

    for name in order:
        _c, p = info[name]
        render_py = p.with_name("render.py")
        subprocess.run(
            [sys.executable, str(render_py)], cwd=ROOT, check=True, timeout=60
        )

    subprocess.run(
        [sys.executable, str(ROOT / "integrate.py")], cwd=ROOT, check=True, timeout=60
    )
    subprocess.run(
        [sys.executable, str(ROOT / "final_report.py")],
        cwd=ROOT,
        check=True,
        timeout=60,
    )


if __name__ == "__main__":
    main()

